import numpy as np

def canary_guardrail_check(ctrl_conv, ctrl_n, can_conv, can_n, p99_ms, err_rate,
                           sla_p99=50.0, max_err=0.005, z_crit=-3.0):
    p1, p2 = ctrl_conv / ctrl_n, can_conv / can_n
    p_pool = (ctrl_conv + can_conv) / (ctrl_n + can_n)
    se = np.sqrt(p_pool * (1.0 - p_pool) * (1.0 / ctrl_n + 1.0 / can_n))
    z = (p2 - p1) / se
    reasons = []
    if p99_ms > sla_p99: reasons.append(f"p99={p99_ms}ms>{sla_p99}ms")
    if err_rate > max_err: reasons.append(f"err={err_rate:.2%}>{max_err:.2%}")
    if z < z_crit: reasons.append(f"conv_drop z={z:.2f}<{z_crit}")
    return ("ROLLBACK", reasons) if reasons else ("PROMOTE", [f"z={z:+.2f}"])

dec_ok = canary_guardrail_check(4200, 100_000, 215, 5_000, p99_ms=39.0, err_rate=0.001)
dec_bad = canary_guardrail_check(4200, 100_000, 155, 5_000, p99_ms=41.0, err_rate=0.001)
assert dec_ok[0] == "PROMOTE" and dec_bad[0] == "ROLLBACK"
print(f"Healthy Canary -> {dec_ok} | Degraded Canary -> {dec_bad}")
